#include <stdlib.h>

int compareInts(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return x - y;
}

int nums[] = {5, 2, 8, 1};
qsort(nums, 4, sizeof(int), compareInts);
// nums الآن: {1, 2, 5, 8}

